import { FormEvent, useCallback, useEffect, useMemo, useState } from 'react'
import {
  Activity, AlertTriangle, Archive, Check, ChevronLeft, ChevronRight,
  CircleAlert, ClipboardCheck, Database, FileClock,
  HardDrive, LoaderCircle, Plus, RefreshCw, Save, Search, Server, Settings2,
  Shield, ShieldAlert, ShieldCheck, UserCog, Users, X,
} from 'lucide-react'
import { apiGet, apiPatch, apiPost, apiPut } from './api'

type Page<T> = { items: T[]; pagination?: { total: number; page: number; limit: number; totalPages: number } }
type AdminRole = { id: string; name: string; displayName: string; description?: string; permissions?: { permission: Permission }[]; _count?: { userRoles: number } }
type Permission = { id: string; code: string; name: string; module: string }
type AdminUser = {
  id: string; username: string; fullName: string; email?: string | null; phone?: string | null
  organizationId?: string | null; organization?: { id: string; name: string; region?: string | null } | null
  status: 'ACTIVE' | 'INACTIVE' | 'BLOCKED'; roles: { id: string; name: string; displayName: string }[]
}
type Organization = { id: string; name: string; region?: string | null; status: string }
type DictionaryCategory = { category: string; totalCount: number }
type DictionaryItem = { id: string; category: string; code: string; nameUz: string; nameRu?: string | null; nameEn?: string | null; description?: string | null; sortOrder: number; isActive: boolean }
type AuditRow = { id: string; username?: string | null; userFullName?: string | null; action: string; entityType: string; entityId?: string | null; ipAddress?: string | null; userAgent?: string | null; createdAt: string; oldValues?: unknown; newValues?: unknown }
type Health = { status: string; timestamp: string; uptime: string; version: string; api: { status: string; responseTimeMs: number; message?: string }; database: { status: string; responseTimeMs: number; message?: string }; scheduler: { status: string; message?: string } }
type MaintenanceState = { enabled: boolean; message: string; updatedAt?: string }
type Metrics = { totalRequests: number; avgResponseTimeMs: number; errorCount: number; activeConnections: number; memoryUsagePercent: number; cpuUsagePercent: number; collectedAt: string }
type SystemLog = { level: string; message: string; context?: string; timestamp: string; metadata?: Record<string, unknown> }
type Settings = { timers: { caseRegistrationDays: number; mediatorAssignmentDays: number; mediationProcessMaxDays: number; agreementExecutionConfirmationDays: number }; fileLimits: { maxFileSizeMb: number; allowedExtensions: string[]; maxFilesCount: number }; general: { platformName: string; supportPhone: string; supportEmail: string }; notifications: { code: string; smsTemplate: string; emailTemplate: string }[] }
type ConfigProposal = { id: string; area: string; current: string; proposed: string; status: string; requestedAt?: string; decisionNote?: string }

const input = 'form-control'
const card = 'rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200/70'
const button = 'inline-flex h-10 items-center justify-center gap-2 rounded-lg bg-slate-950 px-4 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-50'
const secondaryButton = 'inline-flex h-9 items-center justify-center gap-2 rounded-lg border border-slate-200 bg-white px-3 text-xs font-semibold text-slate-700 disabled:opacity-50'
const statusLabels: Record<string, string> = { ACTIVE: 'Faol', INACTIVE: 'Faolsiz', BLOCKED: 'Bloklangan' }

function ErrorBox({ error }: { error: string }) { return error ? <p role="alert" className="mb-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{error}</p> : null }
function PageTitle({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: React.ReactNode }) {
  return <div className="mb-6 flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs font-semibold uppercase tracking-wide text-blue-700">{eyebrow}</p><h1 className="mt-2 text-2xl font-semibold tracking-tight text-slate-950">{title}</h1><p className="mt-1.5 text-sm text-slate-500">{detail}</p></div>{action}</div>
}
function localProposals(): ConfigProposal[] {
  try { const value = JSON.parse(localStorage.getItem('nizolar.admin.config-proposals') || '[]'); return Array.isArray(value) ? value : [] } catch { return [] }
}

export default function AdminWorkspace({ page, onToast, onNavigate }: { page: string; onToast: (message: string) => void; onNavigate: (page: string) => void }) {
  if (page === 'Foydalanuvchilar va rollar') return <UsersWorkspace onToast={onToast} />
  if (page === 'Huquqlar matritsasi') return <PermissionsWorkspace onToast={onToast} />
  if (page === 'Ma’lumotnomalar' || page === 'Spravochniklar') return <DictionariesWorkspace onToast={onToast} />
  if (page === 'Texnik ekspluatatsiya') return <OperationsWorkspace />
  if (page === 'Xavfsizlik va audit' || page === 'Audit jurnali') return <AuditWorkspace onNavigate={onNavigate} initialView={page !== 'Audit jurnali'} />
  if (page === 'SI takliflarini ko‘rib chiqish') return <ProposalsWorkspace onToast={onToast} />
  if (page === 'Tizim sozlamalari') return <SettingsWorkspace onToast={onToast} />
  return <AdminOverview onNavigate={onNavigate} />
}

function AdminOverview({ onNavigate }: { onNavigate: (page: string) => void }) {
  const [health, setHealth] = useState<Health | null>(null)
  const [userCount, setUserCount] = useState<number | null>(null)
  const [auditCount, setAuditCount] = useState<number | null>(null)
  const [error, setError] = useState('')
  const refresh = useCallback(() => {
    setError('')
    Promise.all([apiGet<Health>('/platform/health'), apiGet<Page<AdminUser>>('/admin/users?page=1&limit=1'), apiGet<Page<AuditRow>>('/admin/audit-log?page=1&limit=1')])
      .then(([system, users, audit]) => { setHealth(system); setUserCount(users.pagination?.total ?? users.items.length); setAuditCount(audit.pagination?.total ?? audit.items.length) })
      .catch((cause) => setError(cause instanceof Error ? cause.message : 'Ko‘rsatkichlarni yuklab bo‘lmadi.'))
  }, [])
  useEffect(() => { refresh() }, [refresh])
  const tiles = [
    ['Platforma holati', health?.status === 'healthy' ? 'Barqaror' : health ? 'Tekshiruv kerak' : '—', health?.uptime || 'Serverga ulanish tekshirilmoqda'],
    ['Foydalanuvchilar', userCount ?? '—', 'Tarixiy ma’lumotlar saqlangan holda boshqariladi'],
    ['Audit yozuvlari', auditCount ?? '—', 'O‘zgartirib yoki o‘chirib bo‘lmaydigan jurnal'],
    ['Versiya', health?.version || '—', health?.timestamp ? new Date(health.timestamp).toLocaleString('uz-UZ') : 'Tizim tekshiruviga bog‘liq'],
  ]
  const links = [
    ['Foydalanuvchilar va rollar', 'Hisoblar, vakolatlar, kontaktlar va bloklash', Users],
    ['Ma’lumotnomalar', 'Klassifikatorlarni tahrirlash va faolsizlantirish', Database],
    ['Texnik ekspluatatsiya', 'API, ma’lumotlar bazasi, metrikalar va loglar', Server],
    ['Xavfsizlik va audit', 'Kirishlar va muhim amallar jurnalini filtrlash', ShieldCheck],
  ] as const
  return <section><PageTitle eyebrow="Administrator kabineti" title="Tizim boshqaruvi" detail="Texnik holat va boshqaruv amallarining umumiy ko‘rinishi" action={<button className={secondaryButton} onClick={refresh}><RefreshCw size={14}/>Yangilash</button>} /><ErrorBox error={error}/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{tiles.map(([label, value, caption]) => <article key={String(label)} className={card}><p className="text-sm text-slate-500">{label}</p><p className="mt-3 text-2xl font-semibold">{String(value)}</p><p className="mt-2 text-xs leading-5 text-slate-400">{caption}</p></article>)}</div><div className="mt-5 grid gap-3 md:grid-cols-2">{links.map(([title, description, Icon]) => <button key={title} onClick={() => onNavigate(title)} className={`${card} flex items-center gap-4 text-left transition hover:ring-blue-200`}><span className="flex h-11 w-11 items-center justify-center rounded-xl bg-blue-50 text-blue-700"><Icon size={20}/></span><span className="flex-1"><strong className="block text-sm">{title}</strong><span className="mt-1 block text-xs text-slate-500">{description}</span></span><ChevronRight size={17} className="text-slate-400"/></button>)}</div><p className="mt-5 rounded-xl border border-amber-200 bg-amber-50 p-4 text-xs leading-5 text-amber-900">Zaxira nusxa va tiklash amallari server infratuzilmasiga bog‘liq. Ushbu muhitda backup/restore API mavjud emas; panel bu amal bajarilgandek ko‘rsatmaydi.</p></section>
}

function UsersWorkspace({ onToast }: { onToast: (message: string) => void }) {
  const [users, setUsers] = useState<AdminUser[]>([])
  const [roles, setRoles] = useState<AdminRole[]>([])
  const [organizations, setOrganizations] = useState<Organization[]>([])
  const [selectedId, setSelectedId] = useState('')
  const [selectedRoles, setSelectedRoles] = useState<string[]>([])
  const [search, setSearch] = useState('')
  const [filterStatus, setFilterStatus] = useState('')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [total, setTotal] = useState(0)
  const [adminCount, setAdminCount] = useState(0)
  const [form, setForm] = useState({ email: '', phone: '', organizationId: '', status: 'ACTIVE' })
  const [createForm, setCreateForm] = useState({ username: '', fullName: '', email: '', phone: '', roleName: '' })
  const [creating, setCreating] = useState(false)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const refresh = useCallback(async () => {
    setLoading(true); setError('')
    try {
      const params = new URLSearchParams({ page: String(page), limit: '15', ...(search.trim() ? { search: search.trim() } : {}), ...(filterStatus ? { status: filterStatus } : {}) })
      const [result, roleRows, orgResult, admins] = await Promise.all([apiGet<Page<AdminUser>>(`/admin/users?${params}`), apiGet<AdminRole[]>('/admin/roles'), apiGet<Page<Organization>>('/admin/organizations?page=1&limit=100'), apiGet<Page<AdminUser>>('/admin/users?role=ADMIN&page=1&limit=1')])
      setUsers(result.items); setTotal(result.pagination?.total ?? result.items.length); setTotalPages(result.pagination?.totalPages ?? 1)
      setAdminCount(admins.pagination?.total ?? 0)
      setRoles(roleRows); setOrganizations(orgResult.items || [])
      setSelectedId((current) => result.items.some((user) => user.id === current) ? current : result.items[0]?.id || '')
    } catch (cause) { setError(cause instanceof Error ? cause.message : 'Foydalanuvchilarni yuklab bo‘lmadi.') }
    finally { setLoading(false) }
  }, [page, search, filterStatus])
  useEffect(() => { void refresh() }, [refresh])
  const selected = users.find((user) => user.id === selectedId)
  useEffect(() => {
    if (!selected) return
    setForm({ email: selected.email || '', phone: selected.phone || '', organizationId: selected.organizationId || '', status: selected.status })
    setSelectedRoles(selected.roles.map((role) => role.name))
  }, [selected])
  const save = async () => {
    if (!selected) return
    setSaving(true); setError('')
    try {
      await apiPatch(`/admin/users/${selected.id}`, { email: form.email.trim() || null, phone: form.phone.trim() || null, organizationId: form.organizationId, status: form.status })
      await apiPut(`/admin/users/${selected.id}/roles`, { roles: selectedRoles })
      await refresh(); onToast('Foydalanuvchi va vakolatlari saqlandi.')
    } catch (cause) { setError(cause instanceof Error ? cause.message : 'Foydalanuvchi ma’lumotlarini saqlab bo‘lmadi.') }
    finally { setSaving(false) }
  }
  const create = async (event: FormEvent) => {
    event.preventDefault(); setCreating(true); setError('')
    try {
      await apiPost('/admin/users', { username: createForm.username, fullName: createForm.fullName, email: createForm.email || undefined, phone: createForm.phone || undefined, roleNames: createForm.roleName ? [createForm.roleName] : [], status: 'ACTIVE' })
      setCreateForm({ username: '', fullName: '', email: '', phone: '', roleName: '' }); await refresh(); onToast('Yangi hisob yaratildi.')
    } catch (cause) { setError(cause instanceof Error ? cause.message : 'Hisob yaratilmadi.') }
    finally { setCreating(false) }
  }
  return <section><PageTitle eyebrow="Foydalanuvchilarni boshqarish" title="Foydalanuvchilar va rollar" detail={`Kontaktlar, rollar, hududiy doira va hisob holati · Administratorlar: ${adminCount}/20`} action={<button className={secondaryButton} onClick={() => void refresh()}><RefreshCw size={14}/>Yangilash</button>}/><ErrorBox error={error}/><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_390px]"><div className="space-y-4"><form onSubmit={create} className={card}><div className="mb-4 flex items-center gap-2"><Plus size={17} className="text-blue-700"/><h2 className="font-semibold">Yangi foydalanuvchi</h2></div><div className="grid gap-3 sm:grid-cols-2"><input required className={input} placeholder="Login" value={createForm.username} onChange={(event) => setCreateForm({ ...createForm, username: event.target.value })}/><input required className={input} placeholder="F.I.Sh." value={createForm.fullName} onChange={(event) => setCreateForm({ ...createForm, fullName: event.target.value })}/><input type="email" className={input} placeholder="Elektron pochta" value={createForm.email} onChange={(event) => setCreateForm({ ...createForm, email: event.target.value })}/><input className={input} placeholder="Telefon raqami" value={createForm.phone} onChange={(event) => setCreateForm({ ...createForm, phone: event.target.value })}/></div><div className="mt-3 flex flex-wrap gap-2"><select className={`${input} min-w-[220px] flex-1`} value={createForm.roleName} onChange={(event) => setCreateForm({ ...createForm, roleName: event.target.value })}><option value="">Rolni tanlang (ixtiyoriy)</option>{roles.map((role) => <option key={role.id} value={role.name} disabled={role.name === 'ADMIN' && adminCount >= 20}>{role.displayName}{role.name === 'ADMIN' ? ` (${adminCount}/20)` : ''}</option>)}</select><button disabled={creating} className={button}>{creating ? <LoaderCircle size={15} className="animate-spin"/> : <Plus size={15}/>}Hisob yaratish</button></div></form><div className={card}><div className="flex flex-wrap gap-2"><label className="relative min-w-[200px] flex-1"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input className={`${input} pl-9`} placeholder="F.I.Sh., login, telefon yoki email" value={search} onChange={(event) => { setPage(1); setSearch(event.target.value) }}/></label><select aria-label="Hisob holati" className={`${input} w-auto min-w-36`} value={filterStatus} onChange={(event) => { setPage(1); setFilterStatus(event.target.value) }}><option value="">Barcha holatlar</option><option value="ACTIVE">Faol</option><option value="INACTIVE">Faolsiz</option><option value="BLOCKED">Bloklangan</option></select></div>{loading ? <div className="flex justify-center p-10"><LoaderCircle className="animate-spin text-slate-400"/></div> : <div className="mt-3 divide-y divide-slate-100">{users.map((user) => <button key={user.id} onClick={() => setSelectedId(user.id)} className={`flex w-full items-center gap-3 py-3 text-left ${user.id === selectedId ? 'text-blue-800' : ''}`}><span className={`flex h-9 w-9 items-center justify-center rounded-lg ${user.status === 'ACTIVE' ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-700'}`}><UserCog size={16}/></span><span className="min-w-0 flex-1"><strong className="block truncate text-sm">{user.fullName}</strong><span className="mt-1 block truncate text-xs text-slate-500">{user.username} · {user.roles.map((role) => role.displayName).join(', ') || 'Rol yo‘q'}</span></span><span className={`rounded-full px-2 py-1 text-[10px] ${user.status === 'ACTIVE' ? 'bg-emerald-50 text-emerald-800' : user.status === 'BLOCKED' ? 'bg-red-50 text-red-800' : 'bg-slate-100 text-slate-600'}`}>{statusLabels[user.status]}</span></button>)}{!users.length && <p className="py-8 text-center text-sm text-slate-500">Foydalanuvchilar topilmadi.</p>}</div>}<div className="mt-3 flex items-center justify-between border-t border-slate-100 pt-3 text-xs text-slate-500"><span>Jami {total} ta</span><span className="flex items-center gap-3"><button disabled={page <= 1} onClick={() => setPage((p) => p - 1)}><ChevronLeft size={17}/></button>{page} / {totalPages}<button disabled={page >= totalPages} onClick={() => setPage((p) => p + 1)}><ChevronRight size={17}/></button></span></div></div></div><aside className={`${card} h-fit`}><div className="flex items-center gap-2"><ShieldCheck size={17} className="text-blue-700"/><h2 className="font-semibold">Hisob sozlamalari</h2></div>{selected ? <><p className="mt-4 text-sm font-semibold">{selected.fullName}</p><p className="mt-1 text-xs text-slate-500">{selected.username} · {selected.id.slice(0, 8)}</p><div className="mt-4 space-y-3"><label className="block text-xs font-medium text-slate-600">Elektron pochta<input type="email" className={`${input} mt-1`} value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })}/></label><label className="block text-xs font-medium text-slate-600">Telefon<input className={`${input} mt-1`} value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })}/></label><label className="block text-xs font-medium text-slate-600">Tashkilot / hudud doirasi<select className={`${input} mt-1`} value={form.organizationId} onChange={(event) => setForm({ ...form, organizationId: event.target.value })}><option value="">Cheklanmagan</option>{organizations.filter((org) => org.status === 'ACTIVE').map((org) => <option key={org.id} value={org.id}>{org.name}{org.region ? ` · ${org.region}` : ''}</option>)}</select></label><label className="block text-xs font-medium text-slate-600">Hisob holati<select className={`${input} mt-1`} value={form.status} onChange={(event) => setForm({ ...form, status: event.target.value })}><option value="ACTIVE">Faol</option><option value="INACTIVE">Faolsiz</option><option value="BLOCKED">Bloklash</option></select></label></div><div className="mt-5 border-t border-slate-100 pt-4"><p className="mb-2 text-xs font-semibold text-slate-600">Biriktirilgan rollar</p><div className="max-h-48 space-y-2 overflow-y-auto">{roles.map((role) => <label key={role.id} className="flex items-start gap-2 text-xs"><input type="checkbox" checked={selectedRoles.includes(role.name)} onChange={(event) => setSelectedRoles((values) => event.target.checked ? [...values, role.name] : values.filter((value) => value !== role.name))}/><span>{role.displayName}<span className="mt-0.5 block text-[10px] text-slate-400">{role.name}</span></span></label>)}</div><p className="mt-2 text-[10px] leading-4 text-amber-700">Barcha rollarni olib tashlash hisobning tizim vakolatlarini bekor qiladi. Bloklanganda ishlar tarixi o‘chirilmaydi.</p></div><button disabled={saving} onClick={() => void save()} className={`${button} mt-4 w-full`}>{saving ? <LoaderCircle size={15} className="animate-spin"/> : <Save size={15}/>}Saqlash</button></> : <p className="mt-3 text-sm text-slate-500">Tahrirlash uchun foydalanuvchini tanlang.</p>}</aside></div></section>
}

function PermissionsWorkspace({ onToast }: { onToast: (message: string) => void }) {
  const [roles, setRoles] = useState<AdminRole[]>([]); const [permissions, setPermissions] = useState<Permission[]>([]); const [selectedId, setSelectedId] = useState(''); const [codes, setCodes] = useState<string[]>([]); const [error, setError] = useState(''); const [saving, setSaving] = useState(false)
  const refresh = useCallback(() => { setError(''); Promise.all([apiGet<AdminRole[]>('/admin/roles'), apiGet<Permission[]>('/admin/roles/permissions')]).then(([roleRows, permissionRows]) => { setRoles(roleRows); setPermissions(permissionRows); setSelectedId((id) => roleRows.some((role) => role.id === id) ? id : roleRows[0]?.id || '') }).catch((cause) => setError(cause instanceof Error ? cause.message : 'Vakolatlarni yuklab bo‘lmadi.')) }, [])
  useEffect(() => { refresh() }, [refresh])
  const selected = roles.find((role) => role.id === selectedId)
  useEffect(() => { if (selected) setCodes(selected.permissions?.map((row) => row.permission.code) || []) }, [selected])
  const grouped = useMemo(() => permissions.reduce<Record<string, Permission[]>>((acc, item) => { (acc[item.module] ||= []).push(item); return acc }, {}), [permissions])
  const save = async () => { if (!selected) return; setSaving(true); try { await apiPut(`/admin/roles/${selected.id}/permissions`, { permissionCodes: codes }); refresh(); onToast('Huquqlar matritsasi saqlandi va auditga yozildi.') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Huquqlar saqlanmadi.') } finally { setSaving(false) } }
  return <section><PageTitle eyebrow="Foydalanuvchilarni boshqarish" title="Huquqlar matritsasi" detail="Rollar bo‘yicha tizim amallariga kirish huquqlarini boshqaring." action={<button className={secondaryButton} onClick={refresh}><RefreshCw size={14}/>Yangilash</button>}/><ErrorBox error={error}/><div className="grid gap-5 lg:grid-cols-[260px_1fr]"><aside className={card}>{roles.map((role) => <button key={role.id} onClick={() => setSelectedId(role.id)} className={`mb-1 flex w-full items-center gap-3 rounded-lg p-3 text-left ${role.id === selectedId ? 'bg-blue-50 text-blue-900' : 'hover:bg-slate-50'}`}><Shield size={17}/><span><strong className="block text-sm">{role.displayName}</strong><span className="text-[11px] text-slate-500">{role.name} · {role._count?.userRoles ?? 0} hisob</span></span></button>)}</aside><div className={`${card} min-w-0`}><div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 pb-4"><div><h2 className="font-semibold">{selected?.displayName || 'Rolni tanlang'}</h2><p className="mt-1 text-xs text-slate-500">{selected?.description}</p></div><button disabled={!selected || saving} onClick={() => void save()} className={button}>{saving ? 'Saqlanmoqda…' : <><Save size={15}/>Matritsani saqlash</>}</button></div><div className="mt-4 grid gap-4 md:grid-cols-2">{Object.entries(grouped).map(([module, items]) => <article key={module} className="rounded-xl border border-slate-200 p-4"><h3 className="text-xs font-semibold uppercase tracking-wide text-slate-500">{module}</h3><div className="mt-3 space-y-2">{items.map((permission) => <label key={permission.id} className="flex items-start gap-2 text-xs"><input type="checkbox" checked={codes.includes(permission.code)} onChange={(event) => setCodes((current) => event.target.checked ? [...current, permission.code] : current.filter((code) => code !== permission.code))}/><span><strong className="font-medium">{permission.name}</strong><span className="mt-0.5 block text-[10px] text-slate-400">{permission.code}</span></span></label>)}</div></article>)}</div>{!permissions.length && <p className="py-8 text-center text-sm text-slate-500">Vakolatlar katalogi bo‘sh.</p>}</div></div></section>
}

function DictionariesWorkspace({ onToast }: { onToast: (message: string) => void }) {
  const [categories, setCategories] = useState<DictionaryCategory[]>([]); const [category, setCategory] = useState(''); const [items, setItems] = useState<DictionaryItem[]>([]); const [search, setSearch] = useState(''); const [showInactive, setShowInactive] = useState(false); const [editing, setEditing] = useState<DictionaryItem | null>(null); const [form, setForm] = useState({ code: '', nameUz: '', nameRu: '', nameEn: '', description: '' }); const [error, setError] = useState(''); const [saving, setSaving] = useState(false); const [newCategory, setNewCategory] = useState('')
  const refreshCategories = useCallback(() => { apiGet<DictionaryCategory[]>('/admin/dictionaries').then((rows) => { setCategories(rows); setCategory((current) => current || rows[0]?.category || '') }).catch((cause) => setError(cause instanceof Error ? cause.message : 'Ma’lumotnomalar yuklanmadi.')) }, [])
  const refreshItems = useCallback(() => { if (!category) return; const params = new URLSearchParams({ page: '1', limit: '100', ...(search ? { search } : {}), ...(showInactive ? {} : { isActive: 'true' }) }); apiGet<{ items: DictionaryItem[] }>(`/admin/dictionaries/${encodeURIComponent(category)}?${params}`).then((result) => setItems(result.items || [])).catch((cause) => setError(cause instanceof Error ? cause.message : 'Qiymatlar yuklanmadi.')) }, [category, search, showInactive])
  useEffect(() => { refreshCategories() }, [refreshCategories]); useEffect(() => { refreshItems() }, [refreshItems])
  const openEdit = (row?: DictionaryItem) => { setEditing(row || null); setForm(row ? { code: row.code, nameUz: row.nameUz, nameRu: row.nameRu || '', nameEn: row.nameEn || '', description: row.description || '' } : { code: '', nameUz: '', nameRu: '', nameEn: '', description: '' }) }
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!category) { setError('Avval ma’lumotnoma toifasini tanlang.'); return }; setSaving(true); setError(''); try { if (editing) await apiPatch(`/admin/dictionaries/${encodeURIComponent(category)}/${editing.id}`, form); else await apiPost(`/admin/dictionaries/${encodeURIComponent(category)}`, form); setEditing(null); await refreshItems(); refreshCategories(); onToast(editing ? 'Ma’lumotnoma qiymati yangilandi.' : 'Yangi qiymat qo‘shildi.') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Qiymatni saqlab bo‘lmadi.') } finally { setSaving(false) } }
  const toggleActive = async (row: DictionaryItem) => { try { await apiPatch(`/admin/dictionaries/${encodeURIComponent(category)}/${row.id}`, { isActive: !row.isActive }); await refreshItems(); refreshCategories(); onToast(row.isActive ? 'Qiymat tarixni saqlagan holda faolsizlantirildi.' : 'Qiymat faollashtirildi.') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Holatni o‘zgartirib bo‘lmadi.') } }
  const addCategory = (event: FormEvent) => { event.preventDefault(); const value = newCategory.trim().toLocaleLowerCase('en').replace(/\s+/g, '_'); if (!value) return; setCategory(value); setNewCategory(''); setItems([]); onToast(`“${value}” toifasi uchun birinchi qiymatni qo‘shing.`) }
  return <section><PageTitle eyebrow="Ma’lumotnomalar va klassifikatorlar" title="Markazlashgan ma’lumotlar" detail="Qiymatlarni yarating, tahrirlang yoki tarixni saqlagan holda faolsizlantiring." action={<button className={secondaryButton} onClick={() => { refreshCategories(); refreshItems() }}><RefreshCw size={14}/>Yangilash</button>}/><ErrorBox error={error}/><div className="grid gap-5 xl:grid-cols-[300px_1fr]"><aside className={`${card} h-fit`}><h2 className="font-semibold">Toifalar</h2><div className="mt-3 max-h-[460px] space-y-1 overflow-auto">{categories.map((item) => <button key={item.category} onClick={() => { setCategory(item.category); setEditing(null) }} className={`flex w-full items-center justify-between rounded-lg p-3 text-left text-sm ${category === item.category ? 'bg-blue-50 font-semibold text-blue-900' : 'hover:bg-slate-50'}`}><span>{item.category}</span><span className="text-xs text-slate-400">{item.totalCount}</span></button>)}</div><form onSubmit={addCategory} className="mt-4 border-t border-slate-100 pt-4"><label className="text-xs font-medium text-slate-600">Yangi toifa<input className={`${input} mt-1`} value={newCategory} onChange={(event) => setNewCategory(event.target.value)} placeholder="masalan, currencies"/></label><button className={`${secondaryButton} mt-2 w-full`}><Plus size={14}/>Toifani ochish</button><p className="mt-2 text-[10px] leading-4 text-slate-400">Yangi toifa nomi ro‘yxatda qiymat yaratilgach paydo bo‘ladi.</p></form></aside><div className="space-y-4"><form onSubmit={submit} className={card}><div className="mb-4 flex items-center justify-between gap-2"><div><h2 className="font-semibold">{editing ? 'Qiymatni tahrirlash' : `“${category || 'toifa'}” qiymatini qo‘shish`}</h2><p className="mt-1 text-xs text-slate-500">Eski qiymatlar o‘chirilmaydi — nofaol holatga o‘tkaziladi.</p></div>{editing && <button type="button" className={secondaryButton} onClick={() => openEdit()}><X size={14}/>Bekor qilish</button>}</div><div className="grid gap-3 md:grid-cols-2"><input required className={input} placeholder="Unikal kod" value={form.code} onChange={(event) => setForm({ ...form, code: event.target.value })}/><input required className={input} placeholder="Nomi (o‘zbekcha)" value={form.nameUz} onChange={(event) => setForm({ ...form, nameUz: event.target.value })}/><input className={input} placeholder="Nomi (ruscha)" value={form.nameRu} onChange={(event) => setForm({ ...form, nameRu: event.target.value })}/><input className={input} placeholder="Nomi (inglizcha)" value={form.nameEn} onChange={(event) => setForm({ ...form, nameEn: event.target.value })}/><input className={`${input} md:col-span-2`} placeholder="Tavsif" value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })}/></div><button disabled={saving || !category} className={`${button} mt-3`}>{saving ? 'Saqlanmoqda…' : <><Save size={14}/>{editing ? 'Saqlash' : 'Qiymat qo‘shish'}</>}</button></form><div className={card}><div className="flex flex-wrap items-center gap-2"><label className="relative min-w-[200px] flex-1"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input className={`${input} pl-9`} placeholder="Kod, nom yoki tavsif bo‘yicha qidirish" value={search} onChange={(event) => setSearch(event.target.value)}/></label><label className="flex items-center gap-2 text-xs text-slate-600"><input type="checkbox" checked={showInactive} onChange={(event) => setShowInactive(event.target.checked)}/>Nofaol qiymatlarni ham ko‘rsatish</label></div><div className="mt-3 overflow-x-auto"><table className="w-full min-w-[650px] text-left text-xs"><thead className="text-[10px] uppercase tracking-wide text-slate-400"><tr><th className="py-2">Kod</th><th>Nomi</th><th>Tarjimasi</th><th>Holat</th><th className="text-right">Amallar</th></tr></thead><tbody className="divide-y divide-slate-100">{items.map((row) => <tr key={row.id}><td className="py-3 font-mono">{row.code}</td><td className="font-medium">{row.nameUz}<small className="mt-1 block max-w-[260px] text-slate-400">{row.description}</small></td><td className="text-slate-500">{row.nameRu || '—'}<small className="mt-1 block">{row.nameEn || '—'}</small></td><td><span className={`rounded-full px-2 py-1 ${row.isActive ? 'bg-emerald-50 text-emerald-800' : 'bg-slate-100 text-slate-600'}`}>{row.isActive ? 'Faol' : 'Nofaol'}</span></td><td className="text-right"><button className={secondaryButton} onClick={() => openEdit(row)}>Tahrirlash</button><button className={`${secondaryButton} ml-1`} onClick={() => void toggleActive(row)}>{row.isActive ? 'Faolsizlantirish' : 'Faollashtirish'}</button></td></tr>)}</tbody></table>{!items.length && <p className="py-8 text-center text-sm text-slate-500">Bu toifada qiymatlar yo‘q.</p>}</div></div></div></div></section>
}

function OperationsWorkspace() {
  const [health, setHealth] = useState<Health | null>(null); const [metrics, setMetrics] = useState<Metrics | null>(null); const [logs, setLogs] = useState<SystemLog[]>([]); const [maintenance, setMaintenance] = useState<MaintenanceState>({ enabled: false, message: '' }); const [maintenanceMessage, setMaintenanceMessage] = useState('Rejalashtirilgan texnik xizmat'); const [error, setError] = useState(''); const [loading, setLoading] = useState(false); const [savingMode, setSavingMode] = useState(false)
  const refresh = useCallback(async () => { setLoading(true); setError(''); const [statusResult, metricsResult, logsResult, modeResult] = await Promise.allSettled([apiGet<Health>('/platform/health'), apiGet<Metrics>('/platform/metrics'), apiGet<{ logs: SystemLog[] }>('/platform/logs?page=1&limit=50'), apiGet<MaintenanceState>('/platform/maintenance')]); if (statusResult.status === 'fulfilled') setHealth(statusResult.value); if (metricsResult.status === 'fulfilled') setMetrics(metricsResult.value); if (logsResult.status === 'fulfilled') setLogs(logsResult.value.logs || []); if (modeResult.status === 'fulfilled') setMaintenance(modeResult.value); const unavailable = [statusResult, metricsResult, logsResult].some((result) => result.status === 'rejected'); if (modeResult.status === 'rejected') setError(modeResult.reason instanceof Error ? modeResult.reason.message : 'Xizmat rejimini yuklab bo‘lmadi.'); else if (unavailable && !modeResult.value.enabled) setError('Ayrim texnik ko‘rsatkichlarni yuklab bo‘lmadi.'); setLoading(false) }, [])
  useEffect(() => { void refresh() }, [refresh])
  const toggleMaintenance = async () => { const enabled = !maintenance.enabled; if (enabled && !window.confirm('Texnik xizmat rejimini yoqish barcha API so‘rovlarini (health va ushbu rejimni o‘chirish endpointidan tashqari) vaqtincha to‘xtatadi. Davom etilsinmi?')) return; setSavingMode(true); setError(''); try { const next = await apiPut<MaintenanceState>('/platform/maintenance', { enabled, message: maintenanceMessage }); setMaintenance(next) } catch (cause) { setError(cause instanceof Error ? cause.message : 'Xizmat rejimini o‘zgartirib bo‘lmadi.') } finally { setSavingMode(false) } }
  const Status = ({ label, status, detail }: { label: string; status?: string; detail?: string }) => <div className="flex items-center justify-between gap-3 border-b border-slate-100 py-3 last:border-0"><div><p className="text-sm font-medium">{label}</p><p className="mt-1 text-xs text-slate-500">{detail || 'Holat ma’lumoti yo‘q'}</p></div><span className={`rounded-full px-2.5 py-1 text-[10px] font-semibold ${status === 'healthy' ? 'bg-emerald-50 text-emerald-800' : 'bg-amber-50 text-amber-800'}`}>{status === 'healthy' ? 'Sog‘lom' : status || 'Noma’lum'}</span></div>
  return <section><PageTitle eyebrow="Platforma infratuzilmasi" title="Texnik ekspluatatsiya" detail="API va ma’lumotlar bazasi salomatligi, ishlash metrikalari va nosozlik jurnali." action={<button className={secondaryButton} onClick={() => void refresh()}><RefreshCw size={14}/>{loading ? 'Yangilanmoqda…' : 'Yangilash'}</button>}/><ErrorBox error={error}/><div className="grid gap-5 xl:grid-cols-2"><div className={card}><div className="mb-2 flex items-center gap-2"><Activity size={18} className="text-blue-700"/><h2 className="font-semibold">Xizmat holati</h2></div><Status label="API" status={health?.api.status} detail={health?.api.message}/><Status label="Ma’lumotlar bazasi" status={health?.database.status} detail={health?.database.message}/><Status label="Scheduler" status={health?.scheduler.status} detail={health?.scheduler.message}/><p className="mt-3 text-[11px] text-slate-400">Uptime: {health?.uptime || '—'} · API versiyasi: {health?.version || '—'}</p></div><div className={card}><div className="mb-4 flex items-center gap-2"><Server size={18} className="text-blue-700"/><h2 className="font-semibold">Ishlash ko‘rsatkichlari</h2></div><div className="grid grid-cols-2 gap-3">{[['Jami so‘rov', metrics?.totalRequests],['O‘rtacha javob', metrics ? `${metrics.avgResponseTimeMs} ms` : null],['Xatolar', metrics?.errorCount],['Xotira', metrics ? `${metrics.memoryUsagePercent}%` : null],['Faol ulanish', metrics?.activeConnections],['CPU', metrics ? `${metrics.cpuUsagePercent}%` : null]].map(([name, value]) => <div key={String(name)} className="rounded-xl bg-slate-50 p-3"><p className="text-xs text-slate-500">{name}</p><p className="mt-1 text-lg font-semibold">{value ?? '—'}</p></div>)}</div></div></div><div className={`${card} mt-5`}><div className="mb-3 flex items-center gap-2"><FileClock size={18} className="text-blue-700"/><h2 className="font-semibold">Nosozliklar va server jurnali</h2><span className="ml-auto text-xs text-slate-400">{logs.length} ta oxirgi yozuv</span></div>{logs.length ? <div className="max-h-96 divide-y divide-slate-100 overflow-y-auto">{logs.map((log, index) => <article key={`${log.timestamp}-${index}`} className="flex flex-wrap items-start gap-3 py-3"><span className={`rounded px-2 py-1 text-[10px] font-bold ${log.level === 'ERROR' ? 'bg-red-50 text-red-700' : log.level === 'WARN' ? 'bg-amber-50 text-amber-700' : 'bg-slate-100 text-slate-600'}`}>{log.level}</span><div className="min-w-0 flex-1"><p className="text-xs font-medium">{log.message}</p><p className="mt-1 text-[10px] text-slate-400">{log.context || 'Server'} · {new Date(log.timestamp).toLocaleString('uz-UZ')}</p></div></article>)}</div> : <p className="py-6 text-center text-sm text-slate-500">Jurnal bo‘sh yoki server log API mavjud emas.</p>}</div><div className="mt-5 grid gap-3 md:grid-cols-3"><article className={`${card} md:col-span-1`}><HardDrive className="text-amber-600" size={20}/><h3 className="mt-3 text-sm font-semibold">Zaxira nusxasi</h3><p className="mt-1 text-xs leading-5 text-slate-500">Serverda backup storage va scheduler API ulanmagan; qo‘lda backup yaratish hozircha mavjud emas.</p><span className="mt-3 inline-block rounded-full bg-amber-50 px-2 py-1 text-[10px] text-amber-800">Sozlanmagan</span></article><article className={card}><Archive className="text-amber-600" size={20}/><h3 className="mt-3 text-sm font-semibold">Qayta tiklash</h3><p className="mt-1 text-xs leading-5 text-slate-500">Backup manbasi va tasdiqlangan restore jarayoni mavjud bo‘lmagani uchun amal o‘chirib qo‘yilgan.</p><span className="mt-3 inline-block rounded-full bg-slate-100 px-2 py-1 text-[10px] text-slate-600">Mavjud emas</span></article><article className={card}><Settings2 className="text-blue-700" size={20}/><h3 className="mt-3 text-sm font-semibold">Xizmat rejimi · {maintenance.enabled ? 'Texnik xizmat' : 'Normal'}</h3><p className="mt-1 text-xs leading-5 text-slate-500">{maintenance.enabled ? maintenance.message || 'Rejalashtirilgan texnik xizmat' : 'API normal rejimda ishlaydi.'} Rejim saqlanadi va boshqa API so‘rovlarini bloklaydi.</p>{!maintenance.enabled && <input className={`${input} mt-3`} value={maintenanceMessage} onChange={(event) => setMaintenanceMessage(event.target.value)} placeholder="Foydalanuvchilarga ko‘rsatiladigan izoh"/>}<button onClick={() => void toggleMaintenance()} disabled={savingMode} className={`${secondaryButton} mt-3 ${maintenance.enabled ? 'border-red-200 text-red-700' : ''}`}>{savingMode ? 'Saqlanmoqda…' : maintenance.enabled ? 'Texnik xizmatni tugatish' : 'Texnik xizmatni boshlash'}</button></article></div></section>
}

function AuditLogWorkspace() {
  const [rows, setRows] = useState<AuditRow[]>([]); const [search, setSearch] = useState(''); const [action, setAction] = useState(''); const [fromDate, setFromDate] = useState(''); const [toDate, setToDate] = useState(''); const [error, setError] = useState(''); const [loading, setLoading] = useState(false); const [page, setPage] = useState(1); const [totalPages, setTotalPages] = useState(1); const [details, setDetails] = useState<AuditRow | null>(null)
  const refresh = useCallback(async () => { setLoading(true); setError(''); try { const params = new URLSearchParams({ page: String(page), limit: '25', ...(search ? { search } : {}), ...(action ? { action } : {}), ...(fromDate ? { fromDate } : {}), ...(toDate ? { toDate: `${toDate}T23:59:59.999Z` } : {}) }); const result = await apiGet<Page<AuditRow>>(`/admin/audit-log?${params}`); setRows(result.items); setTotalPages(result.pagination?.totalPages || 1) } catch (cause) { setError(cause instanceof Error ? cause.message : 'Audit jurnalini yuklab bo‘lmadi.') } finally { setLoading(false) } }, [page, search, action, fromDate, toDate])
  useEffect(() => { void refresh() }, [refresh])
  return <section><PageTitle eyebrow="Xavfsizlik va nazorat" title="Audit jurnali" detail="Kirish, ma’lumot o‘zgarishi va hujjat amallarini vaqt hamda IP bo‘yicha ko‘ring. Jurnal faqat o‘qish uchun." action={<button className={secondaryButton} onClick={() => void refresh()}><RefreshCw size={14}/>Yangilash</button>}/><div className="mb-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><label className="relative"><Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input className={`${input} pl-9`} placeholder="Foydalanuvchi yoki amal" value={search} onChange={(event) => { setPage(1); setSearch(event.target.value) }}/></label><select className={input} value={action} onChange={(event) => { setPage(1); setAction(event.target.value) }}><option value="">Barcha amallar</option><option value="LOGIN">Kirish</option><option value="LOGIN_FAILED">Muvaffaqiyatsiz kirish</option><option value="UPDATE">Tahrirlash</option><option value="ROLE_ASSIGN">Rol biriktirish</option><option value="STATUS_CHANGE">Holat o‘zgarishi</option></select><input aria-label="Boshlanish sanasi" className={input} type="date" value={fromDate} onChange={(event) => { setPage(1); setFromDate(event.target.value) }}/><input aria-label="Tugash sanasi" className={input} type="date" value={toDate} onChange={(event) => { setPage(1); setToDate(event.target.value) }}/></div><ErrorBox error={error}/><div className={`${card} overflow-x-auto p-0`}><table className="w-full min-w-[900px] text-left text-xs"><thead className="bg-slate-50 text-[10px] uppercase tracking-wide text-slate-500"><tr><th className="px-4 py-3">Vaqt</th><th>Foydalanuvchi</th><th>Amal / obyekt</th><th>IP manzil</th><th>Qurilma</th><th></th></tr></thead><tbody className="divide-y divide-slate-100">{rows.map((row) => <tr key={row.id}><td className="px-4 py-3 whitespace-nowrap">{new Date(row.createdAt).toLocaleString('uz-UZ')}</td><td>{row.userFullName || row.username || '—'}<small className="block text-slate-400">{row.username}</small></td><td><strong>{row.action}</strong><small className="block text-slate-400">{row.entityType} · {row.entityId || '—'}</small></td><td>{row.ipAddress || '—'}</td><td className="max-w-[180px] truncate" title={row.userAgent || ''}>{row.userAgent || '—'}</td><td><button className={secondaryButton} onClick={() => setDetails(row)}>Tafsilot</button></td></tr>)}</tbody></table>{loading && <div className="flex justify-center p-8"><LoaderCircle className="animate-spin text-slate-400"/></div>}{!loading && !rows.length && <p className="p-10 text-center text-sm text-slate-500">Filtrga mos audit yozuvi yo‘q.</p>}<div className="flex justify-end gap-3 border-t border-slate-100 px-4 py-3 text-xs"><button disabled={page <= 1} onClick={() => setPage((p) => p - 1)}>Oldingi</button><span>{page} / {totalPages}</span><button disabled={page >= totalPages} onClick={() => setPage((p) => p + 1)}>Keyingi</button></div></div>{details && <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 p-4" onClick={() => setDetails(null)}><article className="max-h-[85vh] w-full max-w-2xl overflow-auto rounded-2xl bg-white p-5 shadow-xl" onClick={(event) => event.stopPropagation()}><div className="flex items-start justify-between"><div><p className="text-xs text-slate-500">{details.entityType} · {details.entityId}</p><h2 className="mt-1 font-semibold">{details.action} tafsilotlari</h2></div><button onClick={() => setDetails(null)} aria-label="Yopish"><X size={18}/></button></div><pre className="mt-4 overflow-auto rounded-xl bg-slate-950 p-4 text-[11px] leading-5 text-slate-100">{JSON.stringify({ user: details.userFullName, username: details.username, time: details.createdAt, ip: details.ipAddress, userAgent: details.userAgent, oldValues: details.oldValues, newValues: details.newValues }, null, 2)}</pre><p className="mt-3 text-[11px] text-slate-500">Audit yozuvi o‘zgartirilmaydi va o‘chirilmaydi.</p></article></div>}</section>
}

function SecurityWorkspace({ onNavigate }: { onNavigate: (page: string) => void }) {
  const [failed, setFailed] = useState<AuditRow[]>([])
  const [error, setError] = useState('')
  useEffect(() => {
    apiGet<Page<AuditRow>>('/admin/audit-log?page=1&limit=100&action=LOGIN_FAILED&entityType=AUTH')
      .then((result) => setFailed(result.items || []))
      .catch((cause) => setError(cause instanceof Error ? cause.message : 'Kirish urinishlarini yuklab bo‘lmadi.'))
  }, [])
  const recentSince = Date.now() - 15 * 60 * 1000
  const recentFailures = failed.filter((entry) => new Date(entry.createdAt).getTime() >= recentSince)
  const counts = recentFailures.reduce<Record<string, number>>((result, entry) => { const key = entry.entityId || entry.username || entry.ipAddress || entry.id; result[key] = (result[key] || 0) + 1; return result }, {})
  const suspicious = Object.entries(counts).filter(([, count]) => count >= 5)
  return <section><PageTitle eyebrow="Axborot xavfsizligi" title="Xavfsizlik nazorati" detail="Kirish hodisalari va muhim amallar audit jurnalidan kuzatiladi."/><ErrorBox error={error}/><div className="grid gap-4 md:grid-cols-2"><article className={card}><ShieldAlert size={21} className="text-blue-700"/><h2 className="mt-3 font-semibold">Noto‘g‘ri parol urinishlari</h2><p className="mt-2 text-sm leading-6 text-slate-600">Oxirgi 15 daqiqada {recentFailures.length} ta muvaffaqiyatsiz kirish qayd etilgan. Bitta hisobda 5 ta urinish bo‘lsa, backend hisobni avtomatik bloklaydi va auditga yozadi.</p><button className="mt-4 text-xs font-semibold text-blue-700 underline" onClick={() => onNavigate('Audit jurnali')}>Kirish jurnalini ochish</button></article><article className={card}><ShieldCheck size={21} className="text-blue-700"/><h2 className="mt-3 font-semibold">Ikki bosqichli autentifikatsiya</h2><p className="mt-2 text-sm leading-6 text-slate-600">SMS/push orqali 2FA’ni yoqish va foydalanuvchi bo‘yicha boshqarish uchun server endpointi mavjud emas. Amaldagi kirish OneID, E-IMZO, Mobile ID va parol autentifikatsiyasiga bog‘liq.</p><span className="mt-4 inline-block rounded-full bg-amber-50 px-2.5 py-1 text-[10px] text-amber-800">2FA sozlamasi backend’da ulanmagan</span></article></div>{suspicious.length > 0 && <div className="mt-4 rounded-xl border border-red-200 bg-red-50 p-4"><h2 className="flex items-center gap-2 text-sm font-semibold text-red-900"><AlertTriangle size={16}/>Shubhali faollik aniqlandi</h2><ul className="mt-2 space-y-1 text-xs text-red-800">{suspicious.map(([key, count]) => <li key={key}>{failed.find((entry) => (entry.entityId || entry.username || entry.ipAddress || entry.id) === key)?.userFullName || key}: {count} ta muvaffaqiyatsiz urinish</li>)}</ul><p className="mt-2 text-[11px] text-red-700">Hisoblar backend tomonidan avtomatik ravishda vaqtincha bloklanadi; foydalanuvchi holatini “Foydalanuvchilar va rollar” bo‘limida ko‘rishingiz mumkin.</p><button className="mt-3 text-xs font-semibold underline" onClick={() => onNavigate('Foydalanuvchilar va rollar')}>Bloklangan hisoblarni ko‘rish</button></div>}<div className="mt-4 rounded-xl border border-blue-100 bg-blue-50 p-4 text-xs leading-5 text-blue-900"><strong>Hisobni vaqtincha cheklash:</strong> Foydalanuvchilar va rollar bo‘limida hisob holatini “Bloklash”ga o‘tkazing. Ishlar va audit tarixi saqlanadi.</div></section>
}

function AuditWorkspace({ onNavigate, initialView }: { onNavigate: (page: string) => void; initialView: boolean }) {
  const [security, setSecurity] = useState(initialView)
  return <div><div className="mb-4 flex gap-2"><button onClick={() => setSecurity(true)} className={`${secondaryButton} ${security ? 'border-blue-300 bg-blue-50 text-blue-900' : ''}`}><ShieldAlert size={14}/>Xavfsizlik</button><button onClick={() => setSecurity(false)} className={`${secondaryButton} ${!security ? 'border-blue-300 bg-blue-50 text-blue-900' : ''}`}><ClipboardCheck size={14}/>Audit jurnali</button></div>{security ? <SecurityWorkspace onNavigate={onNavigate}/> : <AuditTableWorkspace/>}</div>
}

function AuditTableWorkspace() {
  return <AuditLogWorkspace />
}

function AuditDataView() {
  const [rows, setRows] = useState<AuditRow[]>([]); const [search, setSearch] = useState(''); const [error, setError] = useState(''); const [loading, setLoading] = useState(false)
  const refresh = useCallback(() => { setLoading(true); apiGet<Page<AuditRow>>(`/admin/audit-log?page=1&limit=50${search ? `&search=${encodeURIComponent(search)}` : '&entityType=AUTH'}`).then((result) => setRows(result.items)).catch((cause) => setError(cause instanceof Error ? cause.message : 'Kirish jurnalini yuklab bo‘lmadi.')).finally(() => setLoading(false)) }, [search])
  useEffect(() => { refresh() }, [refresh])
  return <section><PageTitle eyebrow="Xavfsizlik va nazorat" title="Kirishlar va xavfsizlik hodisalari" detail="Autentifikatsiya tarixini ko‘rish, qidirish va audit yozuvlarini tekshirish." action={<button className={secondaryButton} onClick={refresh}><RefreshCw size={14}/>Yangilash</button>}/><div className="mb-4 flex gap-2"><input className={`${input} max-w-lg`} value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Login, amal yoki IP bo‘yicha qidirish"/><button onClick={refresh} className={secondaryButton}><Search size={14}/>Qidirish</button></div><ErrorBox error={error}/><div className={`${card} divide-y divide-slate-100`}>{rows.map((row) => <article key={row.id} className="flex flex-wrap items-center gap-3 py-3"><span className={`rounded-full px-2 py-1 text-[10px] font-semibold ${row.action === 'LOGIN_FAILED' ? 'bg-red-50 text-red-800' : 'bg-emerald-50 text-emerald-800'}`}>{row.action}</span><div className="min-w-0 flex-1"><p className="text-sm font-medium">{row.userFullName || row.username || 'Noma’lum foydalanuvchi'}</p><p className="mt-1 text-xs text-slate-500">{row.ipAddress || 'IP yo‘q'} · {row.userAgent || 'qurilma ma’lumoti yo‘q'}</p></div><time className="text-xs text-slate-400">{new Date(row.createdAt).toLocaleString('uz-UZ')}</time></article>)}{loading && <div className="p-5 text-center text-sm text-slate-500">Yuklanmoqda…</div>}{!loading && !rows.length && <p className="py-8 text-center text-sm text-slate-500">Autentifikatsiya yozuvlari topilmadi.</p>}</div></section>
}

function ProposalsWorkspace({ onToast }: { onToast: (message: string) => void }) {
  const [proposals, setProposals] = useState<ConfigProposal[]>(localProposals)
  const [note, setNote] = useState<Record<string, string>>({})
  useEffect(() => { const sync = () => setProposals(localProposals()); window.addEventListener('storage', sync); return () => window.removeEventListener('storage', sync) }, [])
  const review = (id: string, status: string) => { const updated = proposals.map((item) => item.id === id ? { ...item, status, decisionNote: note[id] || '', reviewedAt: new Date().toISOString() } : item); setProposals(updated); localStorage.setItem('nizolar.admin.config-proposals', JSON.stringify(updated)); onToast(status === 'TASDIQLANDI' ? 'Taklif tasdiqlandi.' : 'Taklif asoslantirilgan holda rad etildi.') }
  return <section><PageTitle eyebrow="Nazoratli konfiguratsiya" title="SI takliflarini ko‘rib chiqish" detail="Vazirlik kabinetidan yuborilgan o‘zgarish loyihalarini joriy va taklif qilingan holat bilan solishtiring."/><div className="mb-4 flex gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4 text-xs leading-5 text-amber-900"><CircleAlert size={16} className="mt-0.5 shrink-0"/><p>Bu loyihada SI topshiriqlari va tasdiqlash navbati hozir brauzerning lokal saqlashida. Tasdiq konfiguratsiyani serverda o‘zgartirmaydi; markaziy backend approval oqimi ulanmagan.</p></div><div className="space-y-3">{proposals.map((proposal) => <article key={proposal.id} className={card}><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-semibold uppercase text-blue-700">{proposal.area}</p><h2 className="mt-1 font-semibold">{proposal.proposed}</h2><p className="mt-1 text-xs text-slate-400">{proposal.requestedAt ? new Date(proposal.requestedAt).toLocaleString('uz-UZ') : 'Yangi topshiriq'}</p></div><span className={`rounded-full px-2.5 py-1 text-[10px] ${proposal.status.includes('TASDIQ') ? 'bg-emerald-50 text-emerald-800' : proposal.status.includes('RAD') ? 'bg-red-50 text-red-800' : 'bg-amber-50 text-amber-800'}`}>{proposal.status}</span></div><div className="mt-4 grid gap-3 md:grid-cols-2"><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs font-semibold text-slate-500">Joriy holat</p><p className="mt-2 text-sm">{proposal.current}</p></div><div className="rounded-xl bg-blue-50 p-4"><p className="text-xs font-semibold text-blue-800">Taklif etilgan holat</p><p className="mt-2 text-sm">{proposal.proposed}</p></div></div>{proposal.status.includes('kutilmoqda') || proposal.status === 'KUTILMOQDA' ? <><textarea className={`${input} mt-3`} rows={2} placeholder="Tasdiq yoki rad etish izohi" value={note[proposal.id] || ''} onChange={(event) => setNote({ ...note, [proposal.id]: event.target.value })}/><div className="mt-3 flex gap-2"><button className={secondaryButton} onClick={() => review(proposal.id, 'TASDIQLANDI')}><Check size={14}/>Tasdiqlash</button><button className={secondaryButton} onClick={() => review(proposal.id, 'RAD_ETILDI')}><X size={14}/>Rad etish</button></div></> : proposal.decisionNote && <p className="mt-3 text-xs text-slate-500">Izoh: {proposal.decisionNote}</p>}</article>)}{!proposals.length && <div className={`${card} py-12 text-center`}><ClipboardCheck className="mx-auto text-slate-300" size={28}/><p className="mt-3 text-sm font-medium">Ko‘rib chiqiladigan taklif yo‘q</p><p className="mt-1 text-xs text-slate-500">Vazirlik xodimi SI yordamchisidan topshiriq yuborgach, qoralama shu brauzerda paydo bo‘ladi.</p></div>}</div></section>
}

function SettingsWorkspace({ onToast }: { onToast: (message: string) => void }) {
  const defaults: Settings = { timers: { caseRegistrationDays: 3, mediatorAssignmentDays: 5, mediationProcessMaxDays: 30, agreementExecutionConfirmationDays: 10 }, fileLimits: { maxFileSizeMb: 25, allowedExtensions: ['pdf', 'doc', 'docx', 'jpg', 'jpeg', 'png', 'zip'], maxFilesCount: 10 }, general: { platformName: '«Nizolarni muqobil hal etish» elektron platformasi', supportPhone: '1008', supportEmail: 'support@adliya.uz' }, notifications: [] }
  const [settings, setSettings] = useState<Settings>(defaults); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState('')
  const refresh = useCallback(() => { setLoading(true); apiGet<Settings>('/admin/settings').then((value) => setSettings({ ...defaults, ...value, timers: { ...defaults.timers, ...value.timers }, fileLimits: { ...defaults.fileLimits, ...value.fileLimits }, general: { ...defaults.general, ...value.general }, notifications: value.notifications || [] })).catch((cause) => setError(cause instanceof Error ? cause.message : 'Sozlamalar yuklanmadi.')).finally(() => setLoading(false)) }, [])
  useEffect(() => { refresh() }, [refresh])
  const save = async () => { setSaving(true); setError(''); try { await apiPut('/admin/settings', { timers: settings.timers, fileLimits: settings.fileLimits, general: settings.general, notifications: settings.notifications }); onToast('Tizim sozlamalari audit bilan saqlandi.') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Sozlamalar saqlanmadi.') } finally { setSaving(false) } }
  const numberField = (key: keyof Settings['timers'], label: string) => <label key={key} className="text-xs font-medium text-slate-600">{label}<input min={1} type="number" className={`${input} mt-1`} value={settings.timers[key]} onChange={(event) => setSettings({ ...settings, timers: { ...settings.timers, [key]: Number(event.target.value) } })}/></label>
  return <section><PageTitle eyebrow="Tizim sozlamalari" title="Tizim parametrlarini boshqarish" detail="Muddatlar, fayl cheklovlari, umumiy ma’lumot va bildirishnoma shablonlari." action={<button className={secondaryButton} onClick={refresh}><RefreshCw size={14}/>Qayta yuklash</button>}/><ErrorBox error={error}/>{loading ? <div className="flex justify-center p-10"><LoaderCircle className="animate-spin"/></div> : <><div className="grid gap-5 xl:grid-cols-2"><article className={card}><h2 className="font-semibold">Jarayon muddatlari (kun)</h2><div className="mt-4 grid gap-3 sm:grid-cols-2">{numberField('caseRegistrationDays', 'Arizani ro‘yxatga olish')}{numberField('mediatorAssignmentDays', 'Mediator tayinlash')}{numberField('mediationProcessMaxDays', 'Mediatsiya maksimal muddati')}{numberField('agreementExecutionConfirmationDays', 'Kelishuv ijrosini tasdiqlash')}</div></article><article className={card}><h2 className="font-semibold">Fayl cheklovlari</h2><div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="text-xs">Maksimal hajm (MB)<input type="number" min={1} className={`${input} mt-1`} value={settings.fileLimits.maxFileSizeMb} onChange={(event) => setSettings({ ...settings, fileLimits: { ...settings.fileLimits, maxFileSizeMb: Number(event.target.value) } })}/></label><label className="text-xs">Bir yuklashdagi fayllar<input type="number" min={1} className={`${input} mt-1`} value={settings.fileLimits.maxFilesCount} onChange={(event) => setSettings({ ...settings, fileLimits: { ...settings.fileLimits, maxFilesCount: Number(event.target.value) } })}/></label><label className="text-xs sm:col-span-2">Ruxsat etilgan kengaytmalar (vergul bilan)<input className={`${input} mt-1`} value={settings.fileLimits.allowedExtensions.join(', ')} onChange={(event) => setSettings({ ...settings, fileLimits: { ...settings.fileLimits, allowedExtensions: event.target.value.split(',').map((value) => value.trim().replace(/^\./, '')).filter(Boolean) } })}/></label></div></article><article className={`${card} xl:col-span-2`}><h2 className="font-semibold">Platforma va aloqa ma’lumotlari</h2><div className="mt-4 grid gap-3 md:grid-cols-3"><label className="text-xs">Platforma nomi<input className={`${input} mt-1`} value={settings.general.platformName} onChange={(event) => setSettings({ ...settings, general: { ...settings.general, platformName: event.target.value } })}/></label><label className="text-xs">Qo‘llab-quvvatlash telefoni<input className={`${input} mt-1`} value={settings.general.supportPhone} onChange={(event) => setSettings({ ...settings, general: { ...settings.general, supportPhone: event.target.value } })}/></label><label className="text-xs">Elektron pochta<input className={`${input} mt-1`} value={settings.general.supportEmail} onChange={(event) => setSettings({ ...settings, general: { ...settings.general, supportEmail: event.target.value } })}/></label></div></article><article className={`${card} xl:col-span-2`}><h2 className="font-semibold">Bildirishnoma shablonlari</h2><div className="mt-3 space-y-4">{settings.notifications.map((item, index) => <div key={item.code} className="rounded-xl border border-slate-200 p-4"><div className="flex items-center gap-2"><span className="rounded bg-slate-100 px-2 py-1 font-mono text-[10px]">{item.code}</span><button className="ml-auto text-xs text-red-700" onClick={() => setSettings({ ...settings, notifications: settings.notifications.filter((_, i) => i !== index) })}>Olib tashlash</button></div><div className="mt-3 grid gap-3 md:grid-cols-2"><label className="text-xs">SMS matni<textarea rows={3} className={`${input} mt-1`} value={item.smsTemplate} onChange={(event) => setSettings({ ...settings, notifications: settings.notifications.map((row, i) => i === index ? { ...row, smsTemplate: event.target.value } : row) })}/></label><label className="text-xs">Email matni<textarea rows={3} className={`${input} mt-1`} value={item.emailTemplate} onChange={(event) => setSettings({ ...settings, notifications: settings.notifications.map((row, i) => i === index ? { ...row, emailTemplate: event.target.value } : row) })}/></label></div></div>)}</div><button className={`${secondaryButton} mt-3`} onClick={() => setSettings({ ...settings, notifications: [...settings.notifications, { code: '', smsTemplate: '', emailTemplate: '' }] })}><Plus size={14}/>Shablon qo‘shish</button></article></div><button disabled={saving} onClick={() => void save()} className={`${button} mt-5`}>{saving ? 'Saqlanmoqda…' : <><Save size={15}/>Sozlamalarni saqlash</>}</button></>}</section>
}
